/*
 * The Space Effect types (S095 P1 plan §4; S095_P1_IMPLEMENTATION.md §S18):
 * Delay (`dly`), Reverb (`rvb`), Echo (`ech`), one module.
 *
 * Memory (SD1, SD13): the runtime (this union member, <= 100 B) holds the
 * raw rows, the type tag and the block-to-block glides; the coefficients
 * and filter states live in the 448 B header of the arena prefix
 * (sk_state()); the audio lives above the prefix, in the whole usable share:
 *   Delay  the stereo tape, L,R int16 frames, plus 3 guard frames;
 *   Reverb the 64 KB plate ring, then the predelay line (int16, half rate);
 *   Echo   the 16 KB plate ring (quarter rate), then the mono tape (int16).
 * Each ring carries a 32-entry guard mirror (SpaceEffect.c).
 * Nothing moves to make room for a type-change tail (§S18): each type starts
 * its write heads where the tail ends and limits the feed against them.
 * Accessors: EffectsManager.c (registry rows, union), SpaceParameters.c.
 * Affiliates: SpaceKit.h, CrumpBitEffect.h (crumpBit_delaySamples(),
 * crumpBit_delayLimit(): the `tim` law, D3).
 */
#ifndef SPACE_EFFECT_H_
#define SPACE_EFFECT_H_



#define SPACE_TAG_DELAY          0u
#define SPACE_TAG_REVERB         1u
#define SPACE_TAG_ECHO           2u

/* Raw rows 3.. of the largest type (Reverb, 18 rows). */
#define SPACE_ROWS_MAX           18u

/*
 * The smallest share each type plays in (buffer_min_bytes, declarative):
 * every type plays in the minimum share (73,664 B, all voice units
 * claimed).
 */
#define SPACE_MIN_SHARE_BYTES                                            \
    (SK_ARENA_PREF_BYTES - FXBUF_VOICE_UNIT_COUNT * FXBUF_VOICE_UNIT_BYTES)

/*
 * The Space union member (SD13; <= 100 B, asserted in EffectsManager.c).
 *
 * What:
 * - tag: SPACE_TAG_*; flags: SPACE_F_*; rows[]: raw row bytes (index - 3),
 *   written by write_param;
 * - the tape (Delay, Echo): tape_n (frames, without the 3 guard frames),
 *   valid (frames written since the seat, saturating), pos (the write
 *   position in frames, fractional: the tape runs at speed v), d[c] (each
 *   channel's delay in tape frames), v (speed), rph[c] (the reverse head's phase 0..1);
 * - mix (the wet gain the next block ramps from: mix x ducking),
 *   dry (the dry gain, gliding from the outgoing type's), duck (the input
 *   follower, per block);
 * - t_samples/t_bpm/t_row: the `tim` curve's value and the tempo and row
 *   it was worked out for (the curve runs only when they move);
 * - the plate (Reverb, Echo): ring_p (the ring pointer, counts up), pre_w /
 *   pre_n (the predelay line's write index and length), siz (the gliding
 *   size).
 * Lifetime: zeroed by the manager at a switch; space_init() fills it.
 */
typedef struct {
    uint8_t  tag;
    uint8_t  flags;
    uint8_t  rows[SPACE_ROWS_MAX];
    uint8_t  pad;
    uint32_t tape_n;
    uint32_t valid;
    float    pos;
    float    d[2];
    float    v;
    float    rph[2];
    float    mix;
    float    dry;
    float    duck;
    uint32_t ring_p;
    uint32_t pre_w;
    uint32_t pre_n;
    float    siz;
    float    t_samples;
    uint16_t t_bpm;
    uint8_t  t_row;
} SpaceRuntime;

#define SPACE_F_HOLD         0x01u   /* `hld` on */
#define SPACE_F_REVERSE      0x02u   /* `rev` on */
#define SPACE_F_SEATED       0x04u   /* the tape (or ring) is placed */
#define SPACE_F_FRZ_SHM      0x10u   /* `frz` 2: freeze with the shimmer (O12) */
#define SPACE_F_ROUTE_MASK   0x60u   /* `rtg` << 5 (Echo, O16) */

extern const effect_type_ops_t space_delayOps;
extern const effect_type_ops_t space_reverbOps;
extern const effect_type_ops_t space_echoOps;

/*
 * The `tim` clamp (BUFFER_DEPENDENT): the largest `dly`-curve row whose
 * delay fits the tape this share seats at the 1/4 speed floor (D3), at the
 * current tempo. Shared by effective_max and the page label, so both stop
 * at the same row (CrumpBit's rule).
 */
uint8_t space_timeLimit(uint8_t tag, const fx_share_t *share);

/* The Reverb's `pre` clamp, the same rule for its predelay line. */
uint8_t space_preLimit(const fx_share_t *share);

/* The row laws the DSP and the page text share (SpaceParameters.c). */
float space_fbkGain(uint8_t row);      /* 0..1.20, unity at 106 (D4) */
float space_sprRatio(uint8_t row);     /* R/L time 0.5..2 (D23) */
float space_rt60(uint8_t row);         /* `dcy`: 0.3..20 s */

/* A stepped row's stop: value 0..127 in n equal zones (§S18). */
static inline uint8_t space_stop(uint8_t value, uint8_t n)
{
    return (uint8_t)(((uint32_t)((value > 127u) ? 127u : value) * n) >> 7);
}

#endif /* SPACE_EFFECT_H_ */

